-- Тема 11: уточнения по проверке Codex (27 исправлений в 12 вопросах), ключи не меняются.
-- Источник: scripts/questions/082_codex_topic11_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Сколько файлов у небольшой обычной таблицы, когда у неё уже созданы карты свободного пространства и видимости? Индексы и TOAST не считаются.', NULL, NULL, NULL, 'Сколько файлов у небольшой журналируемой таблицы, когда у неё уже созданы карты свободного пространства и видимости? Каждый слой занимает один файл, индексы и TOAST не считаются.'),
        ('question', 'Что происходит с нежурналируемой таблицей после сбоя?', NULL, NULL, NULL, 'Что происходит с нежурналируемой таблицей после аварийного завершения сервера и восстановления?'),
        ('question', 'Строка с длинным значением обновляется, но само длинное значение не меняется. Что происходит в toast-таблице?', NULL, NULL, NULL, 'Значение уже вынесено в TOAST. UPDATE изменяет другой столбец, не затрагивая столбец с вынесенным значением. Что происходит в toast-таблице?'),
        ('question', 'Почему pg_database_size возвращает больше, чем сумма размеров пользовательских таблиц базы?', NULL, NULL, NULL, 'Почему pg_database_size больше суммы pg_total_relation_size по пользовательским таблицам базы?'),
        ('option', 'Для каких объектов существует слой инициализации (init)?', 'Для всех таблиц и индексов обычных баз', 'Для журналируемых таблиц и их индексов', 'Обычным журналируемым таблицам он не нужен.', NULL),
        ('option', 'Для каких объектов существует слой инициализации (init)?', 'Для индексов любых таблиц, но не самих таблиц', 'Для индексов журналируемых таблиц', 'Слой init есть не только у индексов: он есть и у нежурналируемых таблиц и последовательностей.', 'Слой init есть не только у индексов журналируемых таблиц: он есть у нежурналируемых таблиц, их индексов и последовательностей.'),
        ('option', 'Для каких объектов существует слой инициализации (init)?', 'Для нежурналируемых таблиц и их индексов', 'Для отношений с нежурналируемым хранением', 'Слой init есть у нежурналируемых объектов: таблиц, их индексов и последовательностей. По нему объект после сбоя возвращается в начальное состояние: таблица пустая, последовательность с начальным значением.', 'Слой init есть у нежурналируемых таблиц, их индексов и последовательностей. После аварийного восстановления таблица пуста, последовательность возвращается к начальному состоянию.'),
        ('option', 'Сколько файлов у небольшой журналируемой таблицы, когда у неё уже созданы карты свободного пространства и видимости? Каждый слой занимает один файл, индексы и TOAST не считаются.', 'Три: основной слой и две карты', NULL, 'Карта видимости обычно появляется после первой очистки.', 'По одному файлу приходится на основной слой, карту свободного пространства (_fsm) и карту видимости (_vm).'),
        ('option', 'Сколько файлов у небольшой журналируемой таблицы, когда у неё уже созданы карты свободного пространства и видимости? Каждый слой занимает один файл, индексы и TOAST не считаются.', 'Два: основной слой и карта видимости', NULL, 'После очистки файлов обычно три: карта видимости появляется после первой очистки.', 'Пропущена карта свободного пространства, наличие которой задано в условии.'),
        ('option', 'Сколько файлов у небольшой журналируемой таблицы, когда у неё уже созданы карты свободного пространства и видимости? Каждый слой занимает один файл, индексы и TOAST не считаются.', 'Четыре: основной слой, карты и init', NULL, 'Слой init есть только у нежурналируемых таблиц.', 'У журналируемой таблицы слоя init нет.'),
        ('option', 'Что происходит с нежурналируемой таблицей после аварийного завершения сервера и восстановления?', 'Восстанавливается из записей WAL после сбоя', NULL, 'Изменения такой таблицы в журнал не пишутся.', 'Изменения данных нежурналируемой таблицы не записываются в WAL.'),
        ('option', 'Что происходит с нежурналируемой таблицей после аварийного завершения сервера и восстановления?', 'Становится пустой: init копируется на основной слой', 'Очищается с сохранением определения таблицы', 'Таблица остаётся, но без данных: слой init записывается на место основного.', NULL),
        ('option', 'Что такое TOAST?', 'Хранение длинных значений вне страницы', 'Сжатие и/или вынос длинных значений', 'Механизм хранения длинных значений: сжатие и/или вынос в отдельную таблицу. Так длинные значения не мешают версии строки поместиться на страницу.', NULL),
        ('option', 'Что показывает функция pg_table_size?', 'Размер таблицы со всеми её индексами', 'Размер таблицы вместе с её индексами', 'Это pg_total_relation_size.', NULL),
        ('option', 'Что показывает функция pg_table_size?', 'Размер таблицы с toast-частью, без индексов', 'Размер таблицы с TOAST, без её обычных индексов', 'Все слои таблицы и её toast-часть, без обычных индексов.', NULL),
        ('option', 'Какие утверждения верны о системном столбце ctid обычной таблицы?', 'Он уникален среди строк всех таблиц базы данных', 'Он уникален в пределах базы данных', 'Физические адреса ctid могут совпадать в разных таблицах.', NULL),
        ('option', 'Что верно для TOAST?', 'Длинные значения могут сжиматься', NULL, 'При стратегии extended сначала пробуется сжатие, затем вынос.', 'При стратегии EXTENDED сначала пробуется сжатие; если строка всё ещё слишком велика, применяется вынос.'),
        ('option', 'Почему важно, что файлы всех объектов одной базы и одного табличного пространства лежат в одном каталоге?', 'Файловые системы плохо справляются с множеством файлов', 'Много файлов в каталоге может замедлить работу ФС', 'Это нужно учитывать при большом числе объектов: в одном каталоге могут лежать файлы всех таблиц и индексов базы.', 'Файлы объектов одной базы в одном табличном пространстве лежат в одном каталоге; большое число файлов может ухудшить производительность файловой системы.'),
        ('option', 'Какое ограничение действует на размер версии строки?', 'Она может занимать до 1 ГБ на странице', 'Её предельный размер составляет 1 ГБ', 'Около 1 ГБ — предел отдельного значения поля, а хранимая версия строки должна помещаться на странице.', NULL),
        ('option', 'Какое ограничение действует на размер версии строки?', 'Она не больше размера буферного кеша', 'Её предельный размер задаёт shared_buffers', 'Ограничение задаёт размер страницы.', 'shared_buffers задаёт объём буферного кеша; размер хранимой версии строки ограничен страницей.'),
        ('option', 'Значение уже вынесено в TOAST. UPDATE изменяет другой столбец, не затрагивая столбец с вынесенным значением. Что происходит в toast-таблице?', 'Старое значение сразу удаляется из toast-таблицы', 'Старое значение удаляется из toast-таблицы', 'На него продолжает ссылаться новая версия строки.', NULL),
        ('option', 'Значение уже вынесено в TOAST. UPDATE изменяет другой столбец, не затрагивая столбец с вынесенным значением. Что происходит в toast-таблице?', 'Значение заново копируется в toast-таблицу', NULL, 'Копирования не происходит.', 'В этом случае новая версия использует прежнюю внешнюю ссылку, поэтому повторное сохранение значения не требуется.'),
        ('option', 'Почему pg_database_size больше суммы pg_total_relation_size по пользовательским таблицам базы?', 'В размер входят системный каталог и служебные объекты', NULL, 'В размер базы входят также системный каталог и другие служебные объекты: в каждой базе есть свои таблицы каталога и их индексы.', 'В этой сумме уже учтены индексы, TOAST и слои пользовательских таблиц; размер базы дополнительно включает её системные каталоги и другие файлы.'),
        ('option', 'В какой схеме лежит toast-таблица временной таблицы?', 'Схема pg_toast кластера', 'Схема pg_toast этой базы', 'Там лежат toast-таблицы постоянных таблиц.', 'В pg_toast этой базы находятся TOAST-таблицы постоянных таблиц; для временных используется pg_toast_temp_N.'),
        ('explanation', 'Что такое TOAST?', NULL, NULL, 'Любая версия строки должна целиком помещаться на одну страницу.', 'Любая версия строки должна целиком помещаться на одну страницу. TOAST позволяет сжимать значения и/или выносить их в отдельную таблицу, чтобы хранимая версия строки помещалась на странице.'),
        ('explanation', 'Что верно для TOAST?', NULL, NULL, 'Toast-таблицы постоянных таблиц лежат в схеме pg_toast (у временных — в pg_toast_temp_N), а любая версия строки должна помещаться на одну страницу: длинные значения сжимаются и выносятся в toast-таблицу.', 'Toast-таблицы постоянных таблиц лежат в схеме pg_toast (у временных — в pg_toast_temp_N), а любая версия строки должна помещаться на одну страницу: длинные значения могут сжиматься и/или выноситься в toast-таблицу в зависимости от стратегии хранения.'),
        ('explanation', 'Почему pg_database_size больше суммы pg_total_relation_size по пользовательским таблицам базы?', NULL, NULL, 'pg_database_size считает все файлы базы: кроме пользовательских таблиц это системный каталог, индексы, toast-таблицы и служебные слои fsm и vm.', 'pg_database_size считает все файлы базы. Сумма pg_total_relation_size по пользовательским таблицам уже включает их индексы, TOAST и слои fsm и vm; сверх неё в размер базы входят системные каталоги и другие файлы.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
